    # Add random prefix/suffix occasionally to diversify near-misses
    if rng.random() < 0.7:
        data = rng.choice(_PREFIXES) + data
    if rng.random() < 0.7:
        data = data + rng.choice(_SUFFIXES)
    # Optionally insert a single extra character somewhere
    if rng.random() < 0.3 and len(data) > 0:
        pos = rng.randrange(0, len(data))
        ch = rng.choice([b"_", b" ", b"-", b"/", b"." , b"\n"])  # simple ASCII set
        data = data[:pos] + ch + data[pos:]
    return data


def _pick_weighted(rng: random.Random, items: List[str], weights: List[int]) -> str:
    total = sum(weights)
    r = rng.randrange(total)
    upto = 0
    for item, w in zip(items, weights):
        if upto + w > r:
            return item
        upto += w
    return items[-1]


def _generate_valid(rng: random.Random, kind: str) -> bytes:
    if kind == "mode":
        return rng.choice(_MODE)
    if kind == "log":
        return rng.choice(_LOG)
    return rng.choice(_RLIM)


def _generate_near(rng: random.Random, kind: str) -> bytes:
    if kind == "mode":
        base = rng.choice(_MODE_NEAR_SEEDS)
    elif kind == "log":
        base = rng.choice(_LOG_NEAR_SEEDS)
    else:
        base = rng.choice(_RLIM_NEAR_SEEDS)
    base = _mutate_case(rng, base, keep_exact=False)
    return _decorate(rng, base, keep_exact=False)


def _generate_extra(rng: random.Random) -> bytes:
    base = rng.choice(_EXTRAS)
    # Slightly vary extras to improve uniqueness
    if base == b"" and rng.random() < 0.5:
        # produce a small random punctuation string
        length = rng.randint(1, 6)
        charset = b"-_./#,;:\n\t "
        return bytes(rng.choice(charset) for _ in range(length))
    return base


# Public API

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Randomly pick which stub family to target
    target = _pick_weighted(rng, ["mode", "log", "rlim"], [3, 3, 3])

    # Choose production type: mostly valid (to hit success paths), but enough variety for uniqueness
    # 60% valid, 30% near-miss, 10% extras
    p = rng.random()
    if p < 0.60:
        token = _generate_valid(rng, target)
        # Keep exact for valid
        token = _decorate(rng, _mutate_case(rng, token, keep_exact=True), keep_exact=True)
    elif p < 0.90:
        token = _generate_near(rng, target)
    else:
        token = _generate_extra(rng)

    # Ensure byte-size limit
    return token[:4096]
